import test from 'node:test';import assert from 'node:assert/strict';import {designClient} from './fixtures/design-client.mjs';
const plain=x=>JSON.parse(JSON.stringify(x));
function fixture({schema=true}={}){const B=designClient(),def=B.defaultState;if(schema)B.defaultState=()=>{const s=def();s.project.plan.furniture=[];return s;};B.state.project.plan={rooms:[{id:'room',floor:0,name:'Phòng tự bố trí',type:'custom',x:0,y:0,w:6,h:6}],openings:[],fixtures:[],outdoor:[],lockedRoomIds:[],lockedFloors:[],...(schema?{furniture:[]}: {})};B.state.ui.planner.selected='room';return B;}
const item=(id,x=3,y=3)=>({id,roomId:'room',floor:0,modelId:'chair',origin:'customer-added',placementStatus:'present',locked:false,pose:{x,y,z:0,rotationDeg:0},size:{width:.4,depth:.4,height:.94},materialBindings:[{sku:'KEEP-SKU',costTreatment:'owned'}]});
test('C01 absent refuses durable writes rather than creating a disconnected store',()=>{const B=fixture({schema:false}),before=plain(B.state.project);assert.equal(B.addFurniture('room','chair'),false);assert.deepEqual(plain(B.state.project),before);assert.equal(B.furnitureContractReady(),false);});
test('37-degree pose uses rotated footprint, preserves identity/materials, undo/redo and C01 reload',()=>{const B=fixture();B.state.project.plan.furniture=[item('seat')];assert.equal(B.editFurniture('seat',{pose:{rotationDeg:37,x:3.5}}),true);const i=B.resolvedFurniture()[0];assert.equal(i.pose.rotationDeg,37);assert.equal(i.materialBindings[0].sku,'KEEP-SKU');assert.equal(B.roomFurnitureLayout(B.selectedRoom())[0].rotation,37);assert.equal(B.roomFurnitureLayout(B.selectedRoom())[0].pose.x,3.5);assert.match(B.furnitureSvg(B.selectedRoom()),/polygon/);B.undoPlan();assert.equal(B.resolvedFurniture()[0].pose.rotationDeg,0);B.redoPlan();assert.equal(B.resolvedFurniture()[0].pose.rotationDeg,37);const restored=B.mergeState(B.defaultState(),plain(B.state));assert.equal(restored.project.plan.furniture[0].pose.rotationDeg,37);});
test('deleted generated item is tombstoned, not regenerated by style or JSON reload',()=>{const B=fixture();B.state.project.plan.rooms[0].type='bed';const generated=B.resolvedFurniture(),target=generated[0];assert.ok(target);assert.equal(B.editFurniture(target.id,{placementStatus:'removed'}),true);B.state.project.style='Industrial';assert.ok(!B.resolvedFurniture().some(i=>i.id===target.id));assert.ok(B.state.project.plan.furniture.some(i=>i.id===target.id&&i.placementStatus==='removed'));B.state=B.mergeState(B.defaultState(),plain(B.state));assert.ok(!B.resolvedFurniture().some(i=>i.id===target.id));B.undoPlan();assert.ok(B.resolvedFurniture().some(i=>i.id===target.id));});
