test('door swept zone, fixture and corridor are kept clear',()=>{const B=fixture();B.state.project.plan.openings=[{id:'door',roomId:'room',floor:0,kind:'door',side:'north',offset:.5,width:.9}];assert.ok(B.furniturePlacementIssues(item('a',3,.3)).some(x=>/cửa/.test(x)));B.state.project.plan.fixtures=[{id:'altar',roomId:'room',floor:0,x:2.8,y:2.8,w:.6,d:.6,h:1}];assert.ok(B.furniturePlacementIssues(item('a')).some(x=>/fixture/.test(x)));B.state.project.plan.rooms[0].type='corridor';assert.ok(B.furniturePlacementIssues(item('a',4,4)).some(x=>/hành lang/.test(x)));});
test('item, room and floor locks reject mutation; item unlock works',()=>{const B=fixture();B.state.project.plan.furniture=[item('a')];assert.equal(B.editFurniture('a',{locked:true}),true);assert.equal(B.editFurniture('a',{pose:{x:4}}),false);assert.equal(B.editFurniture('a',{locked:false}),true);B.state.project.plan.lockedRoomIds=['room'];assert.equal(B.editFurniture('a',{placementStatus:'removed'}),false);B.state.project.plan.lockedRoomIds=[];B.state.project.plan.lockedFloors=[0];assert.equal(B.editFurniture('a',{pose:{x:4}}),false);});
