test('left/right quick rotation shares history, locks, footprint and normalized stored angles',()=>{const B=fixture();B.state.project.plan.furniture=[item('seat')];assert.equal(B.rotateFurniture('seat',-90),true);assert.equal(B.resolvedFurniture()[0].pose.rotationDeg,270);assert.equal(B.rotateFurniture('seat',135),true);assert.equal(B.resolvedFurniture()[0].pose.rotationDeg,45);B.undoPlan();assert.equal(B.resolvedFurniture()[0].pose.rotationDeg,270);B.redoPlan();assert.equal(B.resolvedFurniture()[0].pose.rotationDeg,45);assert.equal(B.rotateFurniture('seat',NaN),false);B.editFurniture('seat',{locked:true});assert.equal(B.rotateFurniture('seat',90),false);assert.equal(B.resolvedFurniture()[0].materialBindings[0].sku,'KEEP-SKU');});
